<?php
require __DIR__ . '/backend/common.php'; require_admin(); $error=''; $reset_link=$_SESSION['reset_link']??''; unset($_SESSION['reset_link']);
if($_SERVER['REQUEST_METHOD']==='POST'){try{$id=(int)input('id');$account=$conn->execute_query('SELECT u.id FROM users u JOIN password_resets r ON r.user_id=u.id WHERE u.id=? AND u.is_active=1',[$id])->fetch_assoc();if(!$account)throw new InvalidArgumentException('No active reset request found.');$token=bin2hex(random_bytes(32));$conn->execute_query('UPDATE password_resets SET token_hash=?,expires_at=NOW() + INTERVAL 30 MINUTE WHERE user_id=?',[hash('sha256',$token),$id]);$_SESSION['reset_link']='reset-password.php?token='.$token;flash('Reset link created. Share it privately with the verified owner.');go('admin-password-resets.php');}catch(Throwable $e){$error=page_error($e);}}
$requests=$conn->query('SELECT r.*,u.full_name,u.email,u.department FROM password_resets r JOIN users u ON u.id=r.user_id WHERE u.is_active=1 ORDER BY r.requested_at')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Password Resets · Admin</title><link rel="stylesheet" href="portal.css"></head><body class="portal-page"><div class="app-container portal-layout"><?php require __DIR__.'/backend/sidebar.php'; ?><main class="main-content"><div class="live-content"><h1>Password reset requests</h1><p>Verify identity outside the portal before issuing a one-time link.</p><?php require __DIR__.'/backend/admin_nav.php'; ?><?php show_message(); ?><?php if($error): ?><p class="notice error"><?= e($error) ?></p><?php endif; ?><?php if($reset_link): ?><section class="box"><h2>One-time reset link</h2><p><a href="<?= e($reset_link) ?>"><?= e($reset_link) ?></a></p><p class="muted">This link is shown once and expires after 30 minutes.</p></section><?php endif; ?><?php if(!$requests): ?><p class="box empty">No reset requests waiting.</p><?php endif; ?><?php foreach($requests as $request): ?><article class="box"><h2><?= e($request['full_name']) ?></h2><p class="muted"><?= e($request['email']) ?> · requested <?= e($request['requested_at']) ?></p><form method="post"><input type="hidden" name="id" value="<?= (int)$request['user_id'] ?>"><button>Identity verified — create reset link</button></form></article><?php endforeach; ?></div></main></div></body></html>
